using Og.Core.Runtime;

namespace Og.Core.Tests;

/// <summary>
/// Leaving is the one thing the engine cannot actually do. A session belongs to
/// the socket, not to the world, so "escape" has never removed anybody from it —
/// it emits an event, prints a farewell, and leaves the character standing
/// exactly where it was.
///
/// For a long while it said "You have escaped! Congratulations!" anyway. Malcolm
/// arrived on the quay, typed "exit", was congratulated, was still on the quay,
/// looked, read "You've found the exit!", and typed it four more times inside
/// forty-five seconds. Nothing threw. The handler succeeded every time and
/// changed nothing a player could see, which is worse than an error, because an
/// error at least tells you to try something else.
///
/// These fix the shape of that: the world may say goodbye once, must not say it
/// twice, and must stop advertising a door to somebody who has already used it.
/// </summary>
public class LeavingTests
{
    private const string Quay = """
    {
      "spawnLocation": 1,
      "startingItems": ["oar"],
      "items": [ { "name": "oar", "description": "One oar.", "isKey": true } ],
      "locations": [
        {
          "index": 1, "name": "The Quay", "description": "Stone, and the sea against it.",
          "isExit": true,
          "farewell": "You push off, and the quay goes small behind you.",
          "interactions": [
            {
              "interactionId": "quay-leave-again",
              "triggers": ["exit", "leave"],
              "if": ["has_left"],
              "actions": [
                { "action": "describe",
                  "parameters": ["The boat knocks against the stone. Nobody here is holding you."] }
              ]
            }
          ]
        }
      ]
    }
    """;

    private static (GameEngine, Session, CollectingOutputSink, CollectingEventSink) Ready()
    {
        var events = new CollectingEventSink();
        var engine = new GameEngine(World.FromJson(Quay), events, seed: 7);
        var output = new CollectingOutputSink();
        var session = engine.Enter("Malcolm", output);
        output.Clear();
        return (engine, session, output, events);
    }

    [Fact]
    public void LeavingOnceIsTheWorldsOwnFarewell()
    {
        var (engine, session, output, events) = Ready();

        engine.HandleInput(session, "exit");

        Assert.Contains("the quay goes small", output.Text);
        Assert.Single(events.Events, e => e.Type == EventType.Escaped);
    }

    [Fact]
    public void LeavingTwiceDoesNotSayGoodbyeTwice()
    {
        var (engine, session, output, events) = Ready();

        engine.HandleInput(session, "exit");
        output.Clear();
        engine.HandleInput(session, "exit");

        Assert.DoesNotContain("the quay goes small", output.Text);
        Assert.DoesNotContain("Congratulations", output.Text);

        // The milestone is the crossing, not the typing. It happened once.
        Assert.Single(events.Events, e => e.Type == EventType.Escaped);
    }

    [Fact]
    public void AndTheRoomGetsToAnswerTheSecondTimeInsteadOfTheEngine()
    {
        var (engine, session, output, _) = Ready();

        engine.HandleInput(session, "exit");
        output.Clear();
        engine.HandleInput(session, "exit");

        // Asserted on the room's own words, not on the word "already", which the
        // engine's fallback also uses — otherwise this passes when the fall-through
        // is broken and nobody notices.
        Assert.Contains("The boat knocks against the stone", output.Text);
    }

    [Fact]
    public void TheExitIsAdvertisedUntilYouHaveUsedItAndNotAfter()
    {
        var (engine, session, output, _) = Ready();

        engine.HandleInput(session, "look");
        Assert.Contains("You've found the exit!", output.Text);

        engine.HandleInput(session, "exit");
        output.Clear();
        engine.HandleInput(session, "look");

        Assert.DoesNotContain("You've found the exit!", output.Text);
    }
}

